"""Split a potential organization name prefix from a repo's full name

    Returns
    -------
    (None, reponame) or (orgname, reponame)
    """
def split_org_repo(name: Any) -> object {
    split = name.split('/', maxsplit=1);
    if (len(split) < 2) {
        return (None, name);
    } else {
        return (split[0], split[1]);
    }
}

"""Convert number of seconds to the string ``mm:ss``.

    Note: If the number of minutes is greater than 100, it will
    be displayed as such.

    Args:
        secs (int): Number of seconds.

    Returns
        str: String in the format of ``mm:ss``.
    """
def secondsToMMSS(secs: Any) -> object {
    secs = int(secs);
    (minutes, seconds) = divmod(secs, 60);
    return '{:02d}:{:02d}'.format(minutes, seconds);
}

"""
    The Rec.2020 12-bit transfer function.

    Parameters
    ----------
    v : float
        The normalized value to pass through the function.

    Returns
    -------
    float
        A converted value.
    """
def transfer_function_Rec2020_12bit_to_linear(v: Any) -> object {
    a = 1.0993;
    b = 0.0181;
    d = 4.5;
    g = 1.0 / 0.45;
    if (v < (b * d)) {
        return (v / d);
    }
    return pow(((v + (a - 1)) / a), g);
}

"""
    Returns ``True`` is the edge has one end in each selection.

    Parameters
    ----------
    edge: tuple[int, int]
    selection_a: collections.abc.Container[collections.abc.Hashable]
    selection_b: collections.abc.Container[collections.abc.Hashable]

    Returns
    -------
    bool
    """
def _edge_is_between_selections(
    `edge: Any, selection_a: Any, selection_b: Any
) -> object {
    return (
        ((`edge[0] in selection_a) and (`edge[1] in selection_b))
        or ((`edge[1] in selection_a) and (`edge[0] in selection_b))
    );
}

"""Unquotes a header value.

    This does not use the real unquoting but what browsers are actually
    using for quoting.

    :param value: the header value to unquote.
    """
def unquote_header_value(value: Any) -> object {
    if (value and (value[0] == value[-1] == '"')) {
        value = value[1:-1];
    }
    return value;
}

"""Converts the given value (0-255) into its hexadecimal representation"""
def toFloat(val: Any) -> object {
    hex = "0123456789abcdef";
    return float(((hex.find(val[0]) * 16) + hex.find(val[1])));
}

