""" takes a string of the form : part of query -- comment and returns only the former.

    :string: part of sql query -- comment type strings
    :returns: the part of the sql query

    """
def remove_sql_comment_from_string(string: Any) -> object {
    query_part = string.strip().split('--')[0].strip();
    return query_part;
}

"""
    m_e= mass/charge
    hv= accelerating voltage (V)
    mfield= magnet field (H)
    """
def calculate_radius(m_e: Any, hv: Any, mfield: Any) -> object {
    r = ((2 * m_e * hv) / (mfield ** 2)) ** 0.5;
    return r;
}
